403	}
404	
405	/** What went wrong, in words an operator can act on. */
406	function providerProblemWords(record: ProviderRecoveryRecord): string {
407	  const last = record.submissions[record.submissions.length - 1];
408	  const status = last?.httpStatus;
409	  if (record.condition === "AUTH_FAILURE" || status === 401 || status === 403) return "the provider rejected the credentials";
410	  if (record.condition === "QUOTA_EXHAUSTED" || status === 402) return "the provider account is out of quota";
411	  if (record.condition === "RATE_LIMITED" || status === 429) return "the provider is rate limiting requests";
412	  if (record.condition === "OVERLOADED" || status === 503 || status === 529) return "the provider is overloaded";
413	  if (record.condition === "DRAINING") return "the provider is restarting";
414	  if (last?.kind === "timeout") return "the provider did not answer in time";
415	  if (last?.kind === "network_error" || record.condition === "TEMPORARILY_UNAVAILABLE") return "the provider cannot be reached";
416	  return "the provider returned an error";
417	}
418	
419	function minutesWords(ms: number): string {
420	  const minutes = Math.round(ms / 60_000);
421	  return minutes < 1 ? "under a minute" : `about ${minutes} min`;
422	}
423	
424	function rawProviderCause(record: ProviderRecoveryRecord): string {
425	  const last = record.submissions[record.submissions.length - 1];
426	  const parts = [
427	    `condition ${record.condition}${last?.httpStatus ? `, HTTP ${last.httpStatus}` : ""}${last ? `, ${last.kind}, execution ${last.execution}` : ""}`,
428	    last?.message,
429	    record.reason ? `recovery: ${record.reason}` : undefined,
430	    last?.requestId ? `request ${last.requestId}` : undefined,
431	  ];
432	  return redactSecrets(scrubUrls(parts.filter(Boolean).join("\n")));
433	}
434	
435	/**
436	 * The provider-wait status line for one recovery transition (PROBING produces none). Every transition carries the
437	 * same `key`, so the client shows one row that changes instead of a line per attempt (D-06).
438	 */
439	export function providerRecoveryStatus(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): StatusNotice | undefined {
440	  if (record.state === "PROBING") return undefined;
441	  const detail = rawProviderCause(record);
442	  const where = record.endpoint ? ` at ${persistableEndpoint(record.endpoint)}` : "";
443	  const problem = providerProblemWords(record);
444	  switch (record.state) {
445	    case "WAITING": {
446	      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
447	      const left = minutesWords(Math.max(0, record.policy.deadlineMs - record.waitedMs));
448	      const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
449	      const text = `Waiting for the model provider${where}: ${problem}. Retry ${record.submissions.length}, next attempt in ${secs}s; gives up in ${left}. Your work is kept. /details shows the raw error; esc cancels.${discarded}`;
450	      return { text: redactSecrets(text), key: PROVIDER_STATUS_KEY, detail };
451	    }
452	    case "RESUMED":
453	      return { text: `The model provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} resumed.`, key: PROVIDER_STATUS_KEY, detail: `Recovered; the earlier error was:\n${detail}` };
454	    case "CANCELLED":
455	      return { text: "Stopped waiting for the model provider.", key: PROVIDER_STATUS_KEY, detail };
456	    default:
457	      return {
458	        text: redactSecrets(`Nexus stopped retrying the model provider${where}: ${problem}. Check the connection or use /connect, then send your message again. /details shows the raw error.`),
459	        key: PROVIDER_STATUS_KEY,
460	        detail,
461	      };
462	  }
463	}
464	
465	/** The answer to a prompt sent while the provider is still down: short, because the start-up notice already gave the steps. */
466	export function noProviderRefusal(problem: { endpoint: string; endpoints?: string[]; nothingThere?: boolean }): string {
467	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
468	  const why = problem.nothingThere === false ? `could not connect to ${named}` : `nothing answers at ${named}`;
469	  return redactSecrets(`Not sent: no model is connected (${why}). Use /connect or start a local model server, then send it again.`);
470	}
471	
472	/** First run with nothing to talk to: what is missing, what to do next, where to read more. The raw cause goes in `detail`. */
473	export function noProviderNotice(problem: { kind: "unreachable" | "rejected"; endpoint: string; endpoints?: string[]; detail: string; blocking?: boolean; nothingThere?: boolean }): StatusNotice {
474	  if (problem.kind === "rejected" || problem.blocking === false) {
475	    // Only a warning: the start-up check can be refused where chat is not (a token not yet refreshed, a key limited to chat).
476	    // With several endpoints that failed, each is named and the wording does not say how each failed (the detail does).
477	    const many = (problem.endpoints?.length ?? 0) > 1;
478	    const verb = many ? "did not pass" : problem.kind === "rejected" ? "rejected the credentials on" : "did not answer";
479	    return {
480	      text: redactSecrets(
481	        `${many ? problem.endpoints!.join(", ") : problem.endpoint} ${verb} the start-up check. Nexus will still try your messages; ` +
482	          `if they fail, type /connect to sign in again or check the API key and the server. \`nexus doctor\` checks the setup.`,
483	      ),
484	      key: STARTUP_PROVIDER_KEY,
485	      detail: redactSecrets(problem.detail),
486	    };
487	  }
488	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
489	  const missing = problem.nothingThere === false ? `No model is connected: Nexus could not connect to ${named}.` : `No model is connected: nothing answers at ${named}.`;
490	  const text =
491	    `${missing} Next: type /connect to sign in or add an API key, or start a local model server (LM Studio, Ollama, llama.cpp) ` +
492	    `and send your message again. \`nexus doctor\` checks the setup; docs/CLOUD_PROVIDERS.md lists providers.`;
493	  return { text: redactSecrets(text), key: STARTUP_PROVIDER_KEY, detail: redactSecrets(problem.detail) };
494	}
495	
496	/** Lines of a command's output carried in `tool.end` for the transcript preview. */
497	export const TOOL_PREVIEW_LINES = 8;
498	
499	export interface ToolSummary {
500	  summary: string;
501	  lines: number;
502	  preview?: string;
503	  exit_code?: number | null;
504	  duration_ms?: number;
505	  timed_out?: boolean;
506	}
507	
508	/**
509	 * What the transcript shows for a finished tool. A command's JSON result (`stdout`, `stderr`, `exit_code`) becomes a
510	 * real summary (`exit 0 · 122 lines`, or `no output`), the count of its output lines and a bounded preview of them;
511	 * other tools keep the first line of their output (or error) as the summary.
512	 */
513	export function toolSummary(success: boolean, output: string, error?: string): ToolSummary {
514	  const command = commandResult(output);
515	  if (command) {
516	    const body = [command.stdout.trimEnd(), command.stderr.trimEnd()].filter(Boolean).join("\n");
517	    const rows = body ? body.split(/\r?\n/) : [];
518	    const exit = command.timed_out ? "timed out" : command.exit_code === null ? "no exit code" : `exit ${command.exit_code}`;
519	    const failure = success ? "" : (error ?? "").split(/\r?\n/).find((line) => line.trim())?.trim() ?? "";
520	    const summary = failure && !failure.startsWith("{") ? failure : `${exit} · ${rows.length ? `${rows.length} line${rows.length === 1 ? "" : "s"}` : "no output"}`;
521	    return {
522	      summary: redactPlain(summary).replace(/\s+/g, " ").slice(0, MAX_SUMMARY),
523	      lines: rows.length,
524	      preview: (rows.length > TOOL_PREVIEW_LINES ? rows.slice(-TOOL_PREVIEW_LINES) : rows).map((row) => safeTerminal(row).slice(0, 400)).join("\n"),
525	      exit_code: command.exit_code,
526	      ...(command.duration_ms !== undefined ? { duration_ms: command.duration_ms } : {}),
527	      ...(command.timed_out ? { timed_out: true } : {}),
528	    };
529	  }
530	  const text = redactPlain(success ? output || "" : error || output || "").trim();
531	  const first = text.split(/\r?\n/).find((line) => line.trim())?.trim() ?? (success ? "Completed" : "Tool failed");
532	  return { summary: first.replace(/\s+/g, " ").slice(0, MAX_SUMMARY), lines: text ? text.split(/\r?\n/).length : 0 };
533	}
534	
535	/** The structured result of a shell command tool, when `output` is one. */
536	function commandResult(output: string): { stdout: string; stderr: string; exit_code: number | null; duration_ms?: number; timed_out?: boolean } | undefined {
537	  if (!output || output.trimStart()[0] !== "{") return undefined;
538	  try {
539	    const parsed = JSON.parse(output);
540	    if (parsed && typeof parsed === "object" && typeof parsed.stdout === "string" && "exit_code" in parsed) {
541	      return {
542	        stdout: parsed.stdout,
543	        stderr: typeof parsed.stderr === "string" ? parsed.stderr : "",
544	        exit_code: typeof parsed.exit_code === "number" ? parsed.exit_code : null,
545	        ...(typeof parsed.duration_ms === "number" ? { duration_ms: parsed.duration_ms } : {}),
546	        ...(parsed.timed_out === true ? { timed_out: true } : {}),
547	      };
548	    }
549	  } catch {}
550	  return undefined;
551	}
552

