show("error.code", prop("error", "code"));
show("tool.detail.status", prop("tool.detail", "status"));
show("turn", prop("turn.result", "turn"));
show("model_summary", prop("turn.result", "model_summary"));
show("hello.commands", prop("hello", "commands"));
const el = c.getTypeArguments(prop("hello", "commands"))[0]; show(" elem", el);
