// optional named union
const turn = prop("turn.result", "turn");
for (const p of c.getPropertiesOfType(turn)) { const pt = c.getTypeOfSymbol(p); show("  TurnResult." + p.name + (p.flags & SymbolFlags.Optional ? "?" : ""), pt); const nn = c.getNonNullableType(pt); if (nn && nn.id !== pt.id) show("     nonNull", nn); }
console.log("index infos", c.getIndexInfosOfType(turn).length, "sigs", c.getSignaturesOfType(turn, 0).length);
